export const meta = {
  name: "greet-approve",
  description: "Greet someone, then stop for a person to approve",
  inputs: { name: { type: "string", description: "Who to greet", required: true } },
  place: "none",
}

const greeting = await js("return `hello ${input.name}`", { name: args.name }, { label: "greet" })

const approved = await breakpoint(
  "Approve the greeting",
  () => js("return input.greeting", { greeting: greeting.result }, { label: "present" }),
  { show: (step) => step.result },
)

return { greeting: greeting.result, approved: approved.result }

